from _lib import File
F=File('pre2020_gaps2','o-gq','Second fill of pre-2020 models with no second-hand coverage: Yamaha WR250F/WR450F/YZ450FX, KTM 2011 SX two-strokes, 85 SX 2013-2017, XC/XC-W/XC-F years, Husqvarna TE/TX/FX, from magazine tests (knowledge push 2026-11)','KTM',['250 SX'],list(range(2010,2020)))
R=F.R; M='magazine'
Y='Yamaha'; K='KTM'; Q='Husqvarna'

# ---------- Yamaha WR250F 2018-2019
s=F.src(M,"Ultimate Motorcycling - 2018 Yamaha WR250F review","https://ultimatemotorcycling.com/2018/03/13/2018-yamaha-wr250f-review-12-fast-facts/","2018")
A=['WR250F']; YX=[2018,2019]; N='Test bike was a 2018; applied to 2018-2019.'
R('identity','WR250F 2018 update',A,YX,"For 2018 the WR250F got almost all-new engine internals (cams, head, piston, gearbox parts), a recalibrated ECU, a frame based on the current YZ250F with new engine mounts, firmer suspension and a new fork seal wiper. The kickstarter was dropped, leaving electric start only. Engine: 77.0 x 53.6 mm, 13.5:1, 44 mm Keihin throttle body. Travel is 12.2 in front and 12.5 in rear. It weighs 258 lb wet, holds 2.0 gallons, has a 38.0 in seat and listed at $8,099.",{'wet_weight_lb':258,'tank_gal':2.0,'seat_in':38.0,'compression':'13.5:1','msrp_usd_2018':8099,'starter':'electric only'},'OEM',s,notes=N,make=Y)
R('engine_mods','WR250F 2018 uncorked feel',A,YX,"With the throttle stop, airbox restrictor and exhaust restrictor removed for closed-course use (spark arrestor kept), the 2018 WR250F is soft right off the bottom, has good lower-midrange pull and a healthy midrange, and revs strongly to the limiter. The gain over the earlier engine is modest.",{'uncork':'throttle stop, airbox restrictor, exhaust restrictor'},'TUNER',s,notes=N,make=Y)
R('known_issues','WR250F 2018 complaints from testing',A,YX,"Complaints on the 2018 WR250F: the clutch drags when warm and more when cold (find neutral before restarting if it stalls often), first gear is tall for tight single-track (a tooth or two on the rear sprocket helps), it feels loose at speed in sand and loose ground (a steering damper helps), the seat is tall for shorter riders and there are no handguards. The suspension is plush and trail-biased, not a race setup.",{},'TUNER',s,notes=N,make=Y)

# ---------- Yamaha WR450F 2012-2015
s=F.src(M,"Off-Road.com - 2013 Yamaha WR450F review","https://www.off-road.com/dirtbike/review/2013-yamaha-wr450f-review-53764.html?printable","2013")
s2=F.src(M,"Dirt Bike Test - 2016 Yamaha WR450F","https://dirtbiketest.com/bike-tests/2016-yamaha-wr450f/","2016")
A=['WR450F']; YX=[2012,2013,2014,2015]; N='Test bike was a 2013; applied to the 2012-2015 fuel-injected generation.'
R('identity','WR450F 2012-2015 generation',A,YX,"For 2012 the WR450F changed from a carburettor to fuel injection with a tunable ECU, in a chassis that mixed existing WR parts with newer YZ parts. It has a wide-ratio five-speed, electric start, a 48 mm KYB cartridge fork with 11.8 in of travel and a linkage KYB shock with 11.6 in. Claimed wet weight is 273 lb, the tank holds 2.1 gallons and it listed at $8,290 in 2013. The bike was replaced by a YZ450F-based model for 2016.",{'wet_weight_lb':273,'tank_gal':2.1,'gearbox':'5-speed wide ratio','fork':'KYB 48 mm, 11.8 in','msrp_usd_2013':8290},'OEM',s,notes=N,make=Y)
R('power_feel','WR450F 2012-2015 engine feel',A,YX,"The 2012-2015 WR450F has broad, strong power with a snappy, motocross-style delivery. It is racier through the middle and top than a Honda CRF450X but less forgiving on tight, technical obstacles, where it needs careful throttle and clutch. It vibrates less than a YZ. Shifting is notchier than some rivals.",{},'TUNER',s,notes=N,make=Y)
R('engine_mods','WR450F 2012-2015 closed-course uncorking',A,YX,"The 2012-2015 WR450F is delivered with a restrictive muffler baffle and an emissions throttle stop. For closed-course use, riders remove the baffle and fit the throttle housing from the same-year YZ to lose the stop. After that the bike is no longer legal for public land.",{'uncork':'muffler baffle out, YZ throttle housing'},'TUNER',s,notes=N,make=Y)
R('chassis','WR450F 2012-2015 standing against the 2016 bike',A,YX,"Testers who rode both described the 2012-2015 WR450F as a compromise that never stood out, and the YZ450F-based 2016 model as a much better platform. Buyers comparing used bikes should treat 2016 as the real step.",{},'TUNER',s2,'low',make=Y)

# ---------- Yamaha YZ450FX 2019
s=F.src(M,"Cycle News - 2019 Yamaha YZ450FX first impression","https://www.cyclenews.com/2018/09/article/2019-yamaha-yz450fx-first-impression/","2018")
A=['YZ450FX']
R('identity','YZ450FX 2019 redesign',A,[2019],"The YZ450FX was new for 2019 on the current YZ450F platform: new engine, frame, suspension and slimmer, lower bodywork, about six pounds lighter by Yamaha's figures. It gained the free Power Tuner phone app and a two-position map switch on the bar, and has its own 2.2-gallon tank (1.6 on the YZ450F), electric start and a five-speed wide-ratio gearbox. A test bike was listed at 256 lb and $9,499.",{'tank_gal':2.2,'gearbox':'5-speed wide ratio','weight_lb':256,'msrp_usd':9499,'tuner':'phone app, 2 maps on bar switch'},'OEM',s,make=Y)
R('ecu_electronics','YZ450FX 2019: tame the stock map for trail',A,[2019],"With the stock map the 2019 YZ450FX hits hard at low rpm, which is tiring on tight trail and makes it stall. A softer low-rpm map loaded through the app smoothed the bottom-to-mid delivery, cleaned up the fuelling and nearly ended the stalling. Two maps can be kept on the bar switch, so one bike can be set for tight woods and open desert. Testers found first gear a little too low.",{},'TUNER',s,make=Y)

# ---------- KTM 250 SX 2011
s=F.src(M,"Motocross Action - 2011 KTM 250SX test","https://motocrossactionmag.com/2011-ktm-250sx-motocross-test-not-a-warmed-over-bng-bike-but-a-totally-new-two-stroke-for-the-next-generation","2010")
A=['250 SX']
R('identity','250 SX 2011 changes',A,[2011],"The 2011 250 SX got a new chromoly frame and one-piece cast swingarm with a shock 11 mm longer (5 mm more shaft travel) laid over for a more progressive PDS action. In the engine the exhaust port was lowered about 1 mm, the power-valve spring wire went from 2.0 to 1.8 mm and keystone rings were fitted, with a new pipe and a silencer core enlarged from 26 to 28 mm on a more flexible mount with a riveted end cap. Airbox, bodywork and fork settings were also new. List price $6,699.",{'shock':'+11 mm length, +5 mm shaft travel','silencer_core_mm':28,'msrp_usd':6699},'OEM',s,make=K)
R('setups','250 SX 2011 tester fork and shock settings',A,[2011],"The 2011 250 SX came with soft springs. A magazine crew's setup. Fork: 0.46 kg/mm springs (stock 0.44), oil 370 cc (stock 380), compression 12 clicks out, rebound 9 out (stock 12), legs 5 mm up (flush for sand). Shock: 7.2 kg/mm spring (stock 6.9; riders under 170 lb can keep the 6.9), race sag 105 mm, high-speed compression 1 turn out (stock 1-1/2), low-speed compression 10 clicks out (stock 15), rebound 18 out (stock 22).",{'fork_spring':'0.46 kg/mm (stock 0.44)','fork_oil_cc':'370 (stock 380)','fork_comp':'12 out','fork_reb':'9 out (stock 12)','shock_spring':'7.2 kg/mm (stock 6.9)','sag_mm':105,'hsc':'1 turn (stock 1-1/2)','lsc':'10 out (stock 15)','shock_reb':'18 out (stock 22)'},'TUNER',s,make=K)
R('setups','250 SX 2011 jetting',A,[2011],"Testers raced the 2011 250 SX on its stock jetting: 158 main, 42 pilot, N1EI needle on the third clip from the top, 6.5 slide and the air screw at 1-1/2 turns, moved for weather and altitude.",{'main':158,'pilot':42,'needle':'N1EI clip 3','slide':6.5,'air_screw':'1.5 turns'},'TUNER',s,make=K)
R('power_feel','250 SX 2011 power feel',A,[2011],"The 2011 250 SX has a stronger hit just before the midrange than the earlier engine, pulls hard and keeps a good top end; the very bottom is not noticeably better. The delivery is abrupt and takes time to learn. The locking fuel cap is hard to remove and its lipless opening lets dirt in.",{},'TUNER',s,make=K)

# ---------- KTM 150 SX 2011
s=F.src(M,"Motocross Action - 2011 KTM 150SX test","https://motocrossactionmag.com/2011-ktm-150sx-motocross-test-perhaps-the-best-bike-for-riders-looking-to-maximize-the-fun-of-racing","2010")
A=['150 SX']
R('identity','150 SX 2011 changes',A,[2011],"The 2011 150 SX got the new frame (more torsional, less longitudinal stiffness), a one-piece cast swingarm, a shock laid down further with an 11 mm longer shaft and 5 mm more shaft travel, a nylon preload ring, a new airbox and boot, and new rear bodywork. The engine was essentially unchanged from 2010. It is a six-speed with a 38 mm Keihin PWK and a Magura hydraulic clutch, and weighs under 200 lb.",{'gearbox':'6-speed','carb':'Keihin PWK 38','weight_lb':'under 200'},'OEM',s,make=K)
R('setups','150 SX 2011 tester fork and shock settings',A,[2011],"A magazine crew's 2011 150 SX setup. Fork: 0.42 kg/mm springs (0.44 for heavier or faster riders), 350 cc oil, compression 6 clicks out (stock 12), rebound 10 out (stock 12). Shock: 6.3 kg/mm spring, race sag 105 mm, high-speed compression 1-1/4 turns out (stock 1-1/2), low-speed compression 10 clicks out (stock 15), rebound 14 out (stock 22). If free sag is over 35 mm the spring is wrong for the rider; KTM listed springs from 6.0 to 7.2 kg/mm.",{'fork_spring':'0.42 kg/mm (0.44 heavier)','fork_comp':'6 out (stock 12)','fork_reb':'10 out (stock 12)','shock_spring':'6.3 kg/mm','sag_mm':105,'hsc':'1-1/4 turns (stock 1-1/2)','lsc':'10 out (stock 15)','shock_reb':'14 out (stock 22)'},'TUNER',s,make=K)
R('setups','150 SX 2011 jetting and gearing',A,[2011],"The 2011 150 SX pings if it is lean. Testers went up from the stock 182 main to a 185 or 190, with a 40 pilot, NOZI needle and the air screw at 1-1/2 turns. They also added a tooth at the rear, 51 in place of the stock 50.",{'main':'185 or 190 (stock 182)','pilot':40,'needle':'NOZI','air_screw':'1.5 turns','rear_sprocket':'51 (stock 50)'},'TUNER',s,make=K)
R('known_issues','150 SX 2011 things to watch',A,[2011],"On the 2011 150 SX the power is all at the top and it must be kept on the pipe. Keep an eye on the rear sprocket bolts, shift lever bolt and top shock bolt, and look after the nylon preload ring. The crank and head problems of the earlier 144 engine were resolved by this point.",{},'TUNER',s,make=K)

# ---------- KTM 85 SX 2013-2017
s=F.src(M,"Motocross Action - 2014 KTM 85SXS test","https://motocrossactionmag.com/mxas-2014-ktm-85sxs-motocross-test-a-bike-so-special-that-they-sell-out-like-new-iphones-on-the-first-day","2013")
A=['85 SX 17/14','85 SX 19/16']; YX=[2013,2014,2015,2016,2017]; N='Source tested the limited SXS version of this generation; only points it states about the standard 85 SX are recorded.'
R('identity','85 SX 2013-2017 generation',A,YX,"The 2013-2017 85 SX has the overhauled engine with a 47 mm bore, a compact cylinder with a centrifugally controlled exhaust valve and a VForce3 reed block as standard, a six-speed gearbox and hydraulic clutch, in a chromoly frame with an aluminium subframe, 43 mm WP fork and no-linkage PDS shock. The 17/14 swingarm will accept a 16-inch rear wheel. List price was $5,349 in 2013.",{'bore_mm':47,'gearbox':'6-speed','fork':'WP 43 mm','rear':'PDS','msrp_usd_2013':5349},'OEM',s,'low',notes=N,make=K)
R('power_feel','85 SX 2013-2017 power feel',A,YX,"The 2013-2017 85 SX has an expert-level powerband: weak off the bottom and very fast once revved, so the rider has to use the clutch to keep it on the pipe. An aftermarket pipe and silencer is worth roughly 1.5 hp.",{'pipe_gain_hp':'about 1.5'},'TUNER',s,'low',notes=N,make=K)

# ---------- KTM 250/300 XC-W 2013-2016 (from the 2017 comparison)
s=F.src(M,"Dirt Bike Test - 2017 KTM 300 XC-W","https://dirtbiketest.com/bike-tests/2017-ktm-300-xc-w/","2017")
A=['300 XC-W']; YX=[2013,2014,2015,2016]
R('known_issues','300 XC-W 2016 and earlier against the 2017 engine',A,YX,"Testers who moved from the 2016-and-earlier 300 XC-W to the 2017 bike noted what the older one does differently. It has no counterbalancer, so it vibrates more. Its starter drive could wear the engine cases. Its Keihin carburettor is less sensitive to temperature and altitude than the later Mikuni. The front end feels more planted, the brakes bite harder, and it is fussier about rear ride height.",{},'TUNER',s,make=K)

# ---------- KTM 450 XC-F 2015
s=F.src(M,"Dirt Bike Test - 2016 KTM 450 XC-F","https://dirtbiketest.com/bike-tests/2016-ktm-450-xc-f/","2016")
R('known_issues','450 XC-F 2015 4CS fork',['450 XC-F'],[2015],"The 4CS fork on the 2015 450 XC-F was a common complaint: stiff and spiky in the first part and middle of the stroke, with adjusters that confused riders. The 2016 bike's revised 4CS lost the spike and resisted bottoming better, and the 2016 chassis was noticeably lighter.",{},'TUNER',s,make=K)

# ---------- KTM 250 XC 2019 skipped (covered). Husqvarna TE 150 2018
s=F.src(M,"Ultimate Motorcycling - 2018 Husqvarna TE 150 review","https://ultimatemotorcycling.com/2018/08/07/2018-husqvarna-te-150-review-lightweight-fun/","2018")
A=['TE 150']
R('identity','TE 150 2018 layout',A,[2018],"The 2018 TE 150 is a 144 cc power-valve two-stroke with electric start and a kick backup, a six-speed gearbox, a 38 mm Mikuni TMX and 60:1 premix. It has linkage rear suspension with a WP shock (13.0 in travel), the WP Xplor 48 fork (11.8 in) with tool-free adjusters, Magura brakes and a 2.6-gallon tank. It weighs 219 lb with a full tank, has a 37.8 in seat and listed at $8,299. It replaced the TE 125 with a bigger bore and a heavier ignition rotor.",{'displacement_cc':144,'carb':'Mikuni TMX 38','premix':'60:1','tank_gal':2.6,'weight_lb_full':219,'seat_in':37.8,'msrp_usd':8299},'OEM',s,make=Q)
R('power_feel','TE 150 2018 engine feel and fit',A,[2018],"The 2018 TE 150 is torquey for its size with no flat spot and no hit, a strong midrange, and it rarely stalls or runs out on slow climbs. The suspension is soft, absorbs slow hits and stays predictable at speed; heavier or faster riders will want more. It is a technical-trail bike, not one for whoops and big jumps.",{},'TUNER',s,make=Q)

# ---------- Husqvarna TE 250 / TE 300 2017
s=F.src(M,"Cycle News - 2017 Husqvarna TE 250/300 quick spin","https://www.cyclenews.com/2016/08/article/quick-spin-2017-husqvarna-te-250300/","2016")
A=['TE 250','TE 300']
R('identity','TE 250 and TE 300 2017 redesign',A,[2017],"The TE 250 and TE 300 were about 90% new for 2017: a counterbalanced engine (vibration cut by more than half, by the maker's claim) with new ports and exhaust valve, the starter moved below the cases, a six-speed gearbox in place of the five-speed, a 38 mm Mikuni carburettor, and a new frame with skid-plate mounts. The fork is the WP Xplor coil unit (compression left, rebound right, preload on top) and the linkage shock has off-road valving and a softer spring. The bar map switch gives a standard map and a softer one for slippery ground.",{'gearbox':'6-speed (was 5)','carb':'Mikuni TMX 38','fork':'WP Xplor 48','maps':'1 standard, 2 soft'},'OEM',s,make=Q)
R('power_feel','TE 250 against TE 300 (2017)',A,[2017],"Of the 2017 pair, the TE 300 has the torque and roll-on power and rewards short-shifting in the midrange; it does not rev as cleanly or as far as the 250. The TE 250 revs further, carries each gear longer and still pulls well low down, which suits lighter riders. Both were a little rich just off idle as first delivered, and the Mikuni is fussier about altitude than the Keihin it replaced. For soft sand, testers ran full fork preload and opened the rebound to hold the front up.",{},'TUNER',s,make=Q)

# ---------- Husqvarna TX 300 2017 extra (Cycle News first ride)
s=F.src(M,"Cycle News - 2017 Husqvarna TX 300 first ride","https://cyclenews.com/2016/06/article/first-ride-2017-husqvarna-tx-300","2016")
A=['TX 300']
R('setups','TX 300 2017 off-road air-fork baseline',A,[2017],"An off-road baseline for the 2017 TX 300's AER 48 fork from its launch test: 142 psi with compression and rebound both at 12 clicks, for riders of 150-170 lb, and 105-110 mm of rear sag. Add air and compression for motocross. It weighed 216.9 lb without fuel. The air fork is 3.6 lb lighter than the 4CS it replaced. It can feel harsh in very rocky ground.",{'fork_psi':142,'fork_clicks':'12 / 12','sag_mm':'105-110','weight_lb_no_fuel':216.9},'TUNER',s,make=Q)

# ---------- Husqvarna FX 450 2017
s=F.src(M,"Ultimate Motorcycling - 2017 Husqvarna FX 450 first ride","https://ultimatemotorcycling.com/2016/06/08/2017-husqvarna-fx-450-first-ride-review-10-fast-facts/","2016")
A=['FX 450']
R('identity','FX 450 2017: how it differs from the FC 450',A,[2017],"The 2017 FX 450 is the cross-country version of the FC 450: the same SOHC engine with a slower-building delivery, WP AER 48 air fork, an 18-inch rear wheel, a clear 2.2-gallon tank, a removable side stand, a slightly softer shock, two ignition maps (mellow and aggressive) and traction control that works on either map and can be switched while riding. It has a hydraulic clutch and a larger lithium battery for the starter.",{'tank_gal':2.2,'rear_wheel_in':18,'fork':'WP AER 48','maps':2,'traction_control':'yes'},'OEM',s,make=Q)
R('setups','FX 450 2017 fork fix for motocross hits',A,[2017],"At delivered settings the 2017 FX 450's air fork bottomed on heavy motocross landings. About 5 psi more air and six clicks more damping stopped it and made the fork feel more compliant. The mellow map suits tight single-track and the aggressive map the motocross track. The 2.2-gallon tank means extra fuel stops in long races.",{'fork':'+5 psi, +6 clicks'},'TUNER',s,make=Q)

if __name__=='__main__': F.write()
